(() => {
  const game = window.DRIFTWING;
  const { ctx } = game;
  const spawns = ctx.systems.spawns;
  window.__dwCheck = (name, ok, detail) => {
    if (!ok) console.error(`[lightEffect check] ${name} failed: ${detail}`);
    return `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`;
  };
  if (!spawns.debug) throw new Error('engine-lightEffect needs the spawns dev hook (a dev server, or a build with ?dev=1)');
  const engine = spawns.manager.registry.get('lightEffect');
  if (!engine) throw new Error('the lightEffect engine is not registered');
  const callouts = ['{name} {distance} {direction}.', '{name} ahead, {eta}.', 'Look out for the {name}.'];
  const preset = (id, name, params, { lod = { near: 2500, mid: 8000, far: 20000 }, audio = null, category = 'fantasy' } = {}) => Object.freeze({
    id, name, category, kind: 'event', rarity: 'common', heavy: false,
    candidates: { cellSize: 6000, bucketSeconds: 600, chance: 0.1 },
    filters: { biomes: null, timeOfDay: null, altitude: null, weather: null },
    engines: [{ engine: 'lightEffect', params }],
    lod, lure: null, wind: [], audio,
    journal: { title: name, description: 'A lightEffect engine test fixture.' },
    discovery: { radius: 3000, requireInView: true },
    callouts,
    lifetime: { duration: [900, 900], despawn: { distance: 20000, hysteresis: 3000, outOfViewSeconds: 30 } },
  });
  const presets = [
    preset('leStorm', 'Test lightning storm', {
      lightning: { rate: 150, radius: 1800, cloudBase: 1300, groundShare: 0.7, branches: 8, duration: 1.1, flash: 0.8, minCameraDistance: 300 },
      visibility: { day: 1, night: 1 },
    }, { category: 'weather', lod: { near: 6000, mid: 15000, far: 40000 } }),
    preset('leFireflies', 'Test fireflies', {
      swarm: { count: 3000, radius: 160, height: [0.6, 5], intensity: 5, blink: { period: [2, 4.5], duty: 0.3 }, sync: 0.35 },
      visibility: { day: 0, night: 1 },
    }, { category: 'wildlife', lod: { near: 800, mid: 2500, far: 6000 } }),
    preset('leLavaGlow', 'Test lava glow', {
      glows: [
        { layout: 'scatter', count: 14, radius: 45, onGround: true, height: [2, 6], size: [25, 60], colors: [0xff5a1e, 0xff7a2a], intensity: 1.6, flicker: 0.35 },
        { layout: 'scatter', count: 60, radius: 70, onGround: true, height: [1, 3], size: [3, 8], colors: [0xffb040], intensity: 3, flicker: 0.6, wander: { radius: 2, speed: 0.6 } },
      ],
      light: { color: 0xff6a2a, intensity: 8e4, range: 700, offset: [0, 25, 0], flicker: 0.3, night: 0.7 },
      visibility: { day: 0.5, night: 1 },
    }, { category: 'geo', lod: { near: 1500, mid: 5000, far: 12000 } }),
    preset('leCrystals', 'Test crystal glow', {
      glows: [
        { layout: 'ring', count: 9, radius: 90, onGround: true, height: [25, 70], size: [18, 30], colors: [0x7fe8ff, 0xb48cff], intensity: 3, pulse: { period: 5, depth: 0.5 }, shape: 'flare' },
      ],
      visibility: { day: 0.35, night: 1 }, soundIntensity: 'approach',
    }, { lod: { near: 1500, mid: 5000, far: 12000 }, audio: { recipe: 'crystal', params: {} } }),
    preset('leLighthouse', 'Test lighthouse beam', {
      beam: { offset: [0, 40, 0], count: 2, length: 1600, width: [3, 70], intensity: 1.4, period: 10 },
      glows: [{ offset: [0, 40, 0], count: 1, size: [40, 40], colors: [0xfff2d0], intensity: 6, shape: 'flare' }],
      light: { color: 0xfff0d0, intensity: 5e4, range: 600, offset: [0, 40, 0], priority: 1 },
      visibility: { day: 0.1, night: 1 },
    }, { category: 'structure', lod: { near: 3000, mid: 9000, far: 25000 } }),
  ];
  for (const entry of presets) if (!spawns.manager.getPreset(entry.id)) spawns.debug.addPreset(entry);
  window.__dwLe = {
    engine,
    ids: presets.map((entry) => entry.id),
    parts: (id) => spawns.manager.getParts(id),
    /** What dispose must give back: GPU memory, wind sources, sky modifiers and real lights. */
    snapshot() {
      const memory = ctx.renderer.info.memory;
      return {
        geometries: memory.geometries, textures: memory.textures, attributes: memory.attributes,
        wind: ctx.wind.sourceCount, modifiers: ctx.systems.sky.getModifierState().ids.join(','),
        lights: spawns.getStats().lights.active,
      };
    },
    /**
     * Frames a spawn: the craft is moved back metres from it (toward where the craft was), lift
     * metres above the ground on the way to it, flying across the view; the free camera (which stays
     * within 900 m of the craft) sits there looking at the anchor plus lookUp metres.
     */
    frame(id, { back = 400, lift = 60, lookUp = 0 } = {}) {
      const anchor = spawns.manager.getInstance(id).position;
      const player = game.state.player.position;
      const length = Math.hypot(player.x - anchor.x, player.z - anchor.z) || 1;
      const awayX = (player.x - anchor.x) / length;
      const awayZ = (player.z - anchor.z) / length;
      const x = anchor.x + awayX * back;
      const z = anchor.z + awayZ * back;
      let ground = anchor.y;
      for (let step = 0; step <= 8; step++) {
        const share = step / 8;
        ground = Math.max(ground, ctx.world.groundHeight(x + (anchor.x - x) * share * 0.85, z + (anchor.z - z) * share * 0.85), ctx.world.WATER_LEVEL);
      }
      const y = ground + lift;
      const bearing = ctx.util.bearingTo(x, z, anchor.x, anchor.z);
      ctx.systems.flight.resetTo({ x, y: y - 30, z, heading: bearing + 90 });
      return ctx.systems.camera.setFreeCameraPose({ position: { x, y, z }, target: { x: anchor.x, y: anchor.y + lookUp, z: anchor.z } });
    },
    /**
     * Starts presetId on the flattest dry ground within reach of the craft (fireflies want a meadow,
     * not a cliff): candidates on rings around the craft, the smallest slope wins.
     */
    startOnFlat(presetId, { from = 250, to = 1200 } = {}) {
      const player = game.state.player.position;
      let best = null;
      for (let ring = 0; ring < 5; ring++) {
        const distance = from + ((to - from) * ring) / 4;
        for (let index = 0; index < 16; index++) {
          const angle = (index / 16) * Math.PI * 2;
          const x = player.x + Math.cos(angle) * distance;
          const z = player.z + Math.sin(angle) * distance;
          const ground = ctx.world.groundHeight(x, z);
          if (ground < ctx.world.WATER_LEVEL + 3) continue;
          const slope = Math.abs(ctx.world.groundHeight(x + 60, z) - ctx.world.groundHeight(x - 60, z)) + Math.abs(ctx.world.groundHeight(x, z + 60) - ctx.world.groundHeight(x, z - 60));
          if (best === null || slope < best.slope) best = { x, y: ground, z, slope };
        }
      }
      const position = best ?? { x: player.x, y: Math.max(ctx.world.groundHeight(player.x, player.z), ctx.world.WATER_LEVEL), z: player.z };
      return spawns.manager.activate(presetId, { position: { x: position.x, y: position.y, z: position.z }, heading: game.state.player.heading, source: 'debug', force: true });
    },
    /** Resolves once a bolt of spawn id is in flight (for the screenshot), or after timeoutMs. */
    awaitBolt(id, timeoutMs = 6000) {
      const [part] = spawns.manager.getParts(id);
      const start = performance.now();
      return new Promise((resolve) => {
        const tick = () => {
          const state = engine.describe(part);
          if (state.bolts > 0 || performance.now() - start > timeoutMs) {
            resolve(JSON.stringify({ bolts: state.bolts, waitedMs: Math.round(performance.now() - start) }));
            return;
          }
          requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      });
    },
    sun(elevation) {
      ctx.systems.sky.setDayTime(ctx.util.dayTimeForSunElevation(elevation, true), { transition: 0 });
    },
    /** Samples a spawn every frame for a while: the peak sky flash, bolts in flight and lights held. */
    sample(id) {
      const record = { frames: 0, flash: 0, bolts: 0, strikeLight: 0, engineLights: 0, poolLights: 0 };
      window.__dwLe.sampled = record;
      const [part] = spawns.manager.getParts(id);
      const tick = () => {
        if (window.__dwLe.sampled !== record || !spawns.manager.getInstance(id)) return;
        const state = engine.describe(part);
        record.frames++;
        record.flash = Math.max(record.flash, ctx.systems.sky.getModifierState().flash);
        record.bolts = Math.max(record.bolts, state.bolts);
        record.strikeLight += state.strikeLight ? 1 : 0;
        record.engineLights = Math.max(record.engineLights, engine.stats().lights);
        record.poolLights = Math.max(record.poolLights, spawns.getStats().lights.active);
        requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
      return record;
    },
  };
  // Photo mode frames the shots with the free camera; the simulation keeps running (photo mode
  // pauses it by default), so the strikes fire and the glows animate.
  ctx.setPhotoMode(true);
  game.state.paused = false;
  return window.__dwCheck('setup: engine registered, presets added', true, JSON.stringify({ backend: ctx.backend, presets: window.__dwLe.ids, budget: engine.budget }));
})()

(() => {
