(() => {
  const le = window.__dwLe;
  const { ctx, state } = window.DRIFTWING;
  const spawns = ctx.systems.spawns;
  le.budget.push(spawns.forceSpawn('leFireflies', { distance: 300 }), spawns.forceSpawn('leCrystals', { distance: 500 }));
  const engine = le.engine;
  const original = engine.update;
  const meter = { cpu: 0, calls: 0, frame: state.frame, time: performance.now() };
  engine.update = function measuredUpdate(instance, dt, engineCtx) {
    const start = performance.now();
    original.call(engine, instance, dt, engineCtx);
    meter.cpu += performance.now() - start;
    meter.calls++;
  };
  le.meter = meter;
  le.restoreUpdate = () => { engine.update = original; };
  return JSON.stringify({ spawns: le.budget });
})()

(() => {
  const le = window.__dwLe;
  const { ctx, state } = window.DRIFTWING;
  const stats = le.engine.stats();
  const meter = le.meter;
  const frames = Math.max(1, state.frame - meter.frame);
  const cost = {
    frames,
    instances: stats.instances,
    cpuMsPerFrame: Math.round((meter.cpu / frames) * 1000) / 1000,
    cpuMsPerInstance: Math.round((meter.cpu / Math.max(1, meter.calls)) * 1000) / 1000,
    frameMs: Math.round(((performance.now() - meter.time) / frames) * 100) / 100,
  };
  le.restoreUpdate();
  for (const id of le.budget) if (id) ctx.systems.spawns.deactivate(id, 'test');
  const ok = stats.instances === 5 && stats.particles === 3000 + 74 + 1 + 9 && stats.lights <= 2;
  return window.__dwCheck('five light effects: the points in one pool, the lights within budget', ok, JSON.stringify({ stats, cost }));
})()

