  for (const id of le.cycle) if (id) window.DRIFTWING.ctx.systems.spawns.deactivate(id, 'test');
  return JSON.stringify({ peak: le.peak });
})()

(() => {
  const le = window.__dwLe;
  const { ctx } = window.DRIFTWING;
  const spawnStats = ctx.systems.spawns.getStats();
  const now = le.snapshot();
  const stats = le.engine.stats();
  const baseline = le.baseline;
  const ok = Object.keys(baseline).every((key) => now[key] === baseline[key])
    && stats.instances === 0 && stats.particles === 0 && stats.lights === 0 && stats.bolts === 0 && stats.beams === 0
    && spawnStats.leaks.windSources === 0 && spawnStats.leaks.lights === 0;
  return window.__dwCheck('dispose returns GPU memory, lights, bolts, beams and modifiers to the baseline', ok, JSON.stringify({ baseline, peak: le.peak, now, stats, leaks: spawnStats.leaks }));
})()

(() => {
